+// cutAtWord returns s whole when it has at most n runes. Otherwise it returns the longest
+// whole-word prefix that, with the " ..." marker, fits in n runes.
+func cutAtWord(s string, n int) string {
+	r := []rune(s)
+	if len(r) <= n {
+		return s
+	}
+	const marker = " ..."
+	limit := n - len([]rune(marker))
+	for i := limit; i > 0; i-- {
+		if unicode.IsSpace(r[i]) {
+			if text := strings.TrimRightFunc(string(r[:i]), unicode.IsSpace); text != "" {
+				return text + marker
+			}
+		}
+	}
+	return string(r[:limit]) + marker
+}
