package review

import (
	"strings"
	"testing"
	"unicode/utf8"
)

func TestCutAtWord(t *testing.T) {
	words := func(unit string, n int) string {
		return string([]rune(strings.Repeat(unit+" ", n))[:n])
	}
	over := words("abcdefghij", 200)
	if got, want := cutAtWord(over, progressProblemRunes), strings.TrimSuffix(strings.Repeat("abcdefghij ", 14), " ")+" ..."; got != want {
		t.Errorf("200 runes: got %q, want %q", got, want)
	}
	exact := words("abcdefghij", 160)
	if got := cutAtWord(exact, progressProblemRunes); got != exact {
		t.Errorf("160 runes: got %q, want the whole problem", got)
	}
	multi := words("日本語日本語日本語日", 200)
	got := cutAtWord(multi, progressProblemRunes)
	if !utf8.ValidString(got) || utf8.RuneCountInString(got) > progressProblemRunes || !strings.HasSuffix(got, " ...") || strings.Count(got, "日本語日本語日本語日") != 14 {
		t.Errorf("multi-byte: got %q", got)
	}
}

